# L05 r07 (ข้อ 61–70) เติมความลึกช่องที่สั้นกว่าเกณฑ์ — ตั้งค่าเป็นข้อความเต็ม รันซ้ำได้
import json
F='/home/claude/ac-mdcu/parts/fill/l05_r07.json'
D=json.load(open(F))
def S(n,**kw):
    q=D[str(n)]
    for k,v in kw.items():
        if k=='wrong':
            for c,t in v.items(): q['wrong'][c]=t
        else: q[k]=v

